package utils.ui;

import dev.tamboui.layout.Rect;
import dev.tamboui.buffer.Buffer;
import dev.tamboui.buffer.Cell;
import dev.tamboui.style.Color;
import dev.tamboui.style.Style;
import dev.tamboui.terminal.Frame;
import dev.tamboui.text.CharWidth;
import dev.tamboui.widgets.block.Block;
import dev.tamboui.widgets.gauge.Gauge;
import dev.tamboui.widgets.block.Borders;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;

// Generated by ChatGPT-6-Astra; for ui drawing
public final class UiDrawing { //shares terminal colors, bordered boxes & clipped text rendering
    public static final Style base = Style.EMPTY.fg(Color.rgb(187, 194, 207)).bg(Color.rgb(40, 44, 52));
    //foreground > background
    public static final Style muted = Style.EMPTY.fg(Color.rgb(156, 160, 164));
    public static final Style cyan = Style.EMPTY.fg(Color.rgb(70, 217, 255));
    public static final Style green = Style.EMPTY.fg(Color.rgb(152, 190, 101));
    public static final Style amber = Style.EMPTY.fg(Color.rgb(236, 190, 123));
    public static final Style red = Style.EMPTY.fg(Color.rgb(255, 108, 107));

    private static final Pattern CONTROLS = Pattern.compile("\\p{Cntrl}");

    // Reuse immutable cells instead of patching a new style for every column on every redraw.
    private static final Map<Style, Cell> lineCells = Map.of(
            base, new Cell(" ", base), muted, new Cell(" ", base.patch(muted)),
            cyan, new Cell(" ", base.patch(cyan)), green, new Cell(" ", base.patch(green)),
            amber, new Cell(" ", base.patch(amber)), red, new Cell(" ", base.patch(red)));

    private record BoxKey(int width, int height, String title) {}

    // UI-thread only. Bound retained templates so terminal resizing cannot grow the cache indefinitely.
    private static final Map<BoxKey, Buffer> boxes = new LinkedHashMap<>(16, 0.75f, true) {
        @Override protected boolean removeEldestEntry(Map.Entry<BoxKey, Buffer> eldest) {
            return size() > 16;
        }
    };

    private UiDrawing() {}

    public static Rect box(Frame frame, Rect area, String title) {
        if (!area.isEmpty()) {
            var key = new BoxKey(area.width(), area.height(), title);
            Buffer border = boxes.computeIfAbsent(key, ignored -> {
                var buffer = Buffer.empty(new Rect(0, 0, area.width(), area.height()));
                buffer.fill(buffer.area(), lineCells.get(base));
                Block.builder().borders(Borders.ALL).title(" " + title + " ").borderStyle(muted)
                        .build().render(buffer.area(), buffer);
                return buffer;
            });
            // Copy only the perimeter; leave content inside nested boxes intact.
            for (int x = 0; x < area.width(); x++) {
                frame.buffer().set(area.x() + x, area.y(), border.get(x, 0));
                frame.buffer().set(area.x() + x, area.bottom() - 1, border.get(x, area.height() - 1));
            }
            for (int y = 1; y < area.height() - 1; y++) {
                frame.buffer().set(area.x(), area.y() + y, border.get(0, y));
                frame.buffer().set(area.right() - 1, area.y() + y, border.get(area.width() - 1, y));
            }
        }
        return new Rect(area.x() + 1, area.y() + 1, Math.max(0, area.width() - 2), Math.max(0, area.height() - 2));
    }

    public static void drawLine(Frame frame, Rect area, int row, String value, Style style) {
        if (row < 0 || row >= area.height()) return; //stops if row is outside available area
        Cell blank = lineCells.get(style);
        if (blank == null) blank = new Cell(" ", base.patch(style));
        frame.buffer().fill(new Rect(area.x(), area.y() + row, area.width(), 1), blank);
        // The row already has its final style; an empty patch avoids per-character style allocation.
        frame.buffer().setString(area.x(), area.y() + row, CharWidth.truncateWithEllipsis(safeText(value), area.width(), CharWidth.TruncatePosition.END), Style.EMPTY);
        //draws text on that row > shortening it if its too long
    }

    // Single-row borders and a dim track show the full bar without using extra student rows.
    public static void drawProgressBar(Frame frame, Rect area, double ratio, String label) {
        if (area.width() < 2 || area.height() < 1) return;
        drawLine(frame, new Rect(area.x(), area.y(), 1, 1), 0, "[", muted);
        drawLine(frame, new Rect(area.x() + area.width() - 1, area.y(), 1, 1), 0, "]", muted);
        if (area.width() == 2) return;
        frame.renderWidget(Gauge.builder().ratio(ratio).label(label)
                .style(base.bg(Color.rgb(62, 68, 80))).gaugeStyle(cyan).build(),
                new Rect(area.x() + 1, area.y(), area.width() - 2, 1));
    }

    public static String safeText(String value) { //replaces control characters with spaces to keep terminal display tidy
        return CONTROLS.matcher(value).replaceAll(" ");
        //keep user data from injecting terminal control codes
    }
}
